package com.banktabstorage;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import net.runelite.client.util.Text;

final class BankTabStorageCodec
{
    private static final int MAX_TEXT_LENGTH = 5_000_000;
    private static final int MAX_LAYOUT_INDEX = 9999;
    private final Gson gson;

    BankTabStorageCodec(Gson gson)
    {
        this.gson = gson.newBuilder().setPrettyPrinting().create();
    }

    String encode(List<StoredBankTag> tabs)
    {
        return gson.toJson(new BankTabStorageData(tabs));
    }

    List<StoredBankTag> decode(String text)
    {
        if (text == null || text.trim().isEmpty())
        {
            throw new IllegalArgumentException("The clipboard is empty");
        }
        String normalized = text.trim();
        if (normalized.length() > MAX_TEXT_LENGTH)
        {
            throw new IllegalArgumentException("The clipboard data is too large");
        }
        if (normalized.startsWith("banktags,"))
        {
            return List.of(decodeRuneLiteTab(normalized));
        }
        try
        {
            JsonObject root = gson.fromJson(normalized, JsonObject.class);
            if (root == null)
            {
                throw new IllegalArgumentException("The clipboard does not contain Bank Tab Storage data");
            }
            BankTabStorageData data = gson.fromJson(root, BankTabStorageData.class);
            return data.validatedTabs();
        }
        catch (IllegalArgumentException exception)
        {
            throw exception;
        }
        catch (RuntimeException exception)
        {
            throw new IllegalArgumentException("The clipboard does not contain valid Bank Tab Storage data", exception);
        }
    }

    private StoredBankTag decodeRuneLiteTab(String text)
    {
        List<String> values = Text.fromCSV(text);
        if (values.size() < 4 || !"banktags".equals(values.get(0)) || !"1".equals(values.get(1)))
        {
            throw new IllegalArgumentException("The RuneLite Bank Tags export is invalid");
        }
        String name = StoredBankTag.normalizeName(values.get(2));
        int iconItemId = parseInt(values.get(3), "icon item ID");
        Set<Integer> items = new LinkedHashSet<>();
        List<Integer> layout = null;
        int index = 4;
        while (index < values.size() && !"layout".equals(values.get(index)))
        {
            items.add(parseInt(values.get(index), "item ID"));
            index++;
        }
        if (index < values.size())
        {
            index++;
            if ((values.size() - index) % 2 != 0)
            {
                throw new IllegalArgumentException("The RuneLite Bank Tags layout is invalid");
            }
            layout = new ArrayList<>();
            while (index < values.size())
            {
                int layoutIndex = parseInt(values.get(index++), "layout position");
                int itemId = parseInt(values.get(index++), "layout item ID");
                if (layoutIndex < 0 || layoutIndex > MAX_LAYOUT_INDEX || itemId < 0)
                {
                    throw new IllegalArgumentException("The RuneLite Bank Tags layout is invalid");
                }
                while (layout.size() <= layoutIndex)
                {
                    layout.add(-1);
                }
                layout.set(layoutIndex, itemId);
                items.add(itemId);
            }
        }
        return new StoredBankTag(name, iconItemId, new ArrayList<>(items), layout, false, false).validatedCopy();
    }

    private int parseInt(String value, String label)
    {
        try
        {
            return Integer.parseInt(value);
        }
        catch (NumberFormatException exception)
        {
            throw new IllegalArgumentException("The RuneLite Bank Tags " + label + " is invalid", exception);
        }
    }
}

package com.banktabstorage;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

final class BankTabStorageData
{
    static final String KIND = "bank-tab-storage";
    private static final String LEGACY_KIND = "bank-tags-storage";
    static final int VERSION = 1;
    private static final int MAX_TABS = 500;
    private String kind;
    private int version;
    private List<StoredBankTag> tabs;

    private BankTabStorageData()
    {
    }

    BankTabStorageData(List<StoredBankTag> tabs)
    {
        this.kind = KIND;
        this.version = VERSION;
        this.tabs = copyTabs(tabs);
    }

    List<StoredBankTag> validatedTabs()
    {
        if ((!KIND.equals(kind) && !LEGACY_KIND.equals(kind)) || version != VERSION)
        {
            throw new IllegalArgumentException("The clipboard does not contain a supported Bank Tab Storage export");
        }
        return copyTabs(tabs);
    }

    private static List<StoredBankTag> copyTabs(List<StoredBankTag> source)
    {
        if (source == null || source.size() > MAX_TABS)
        {
            throw new IllegalArgumentException("The saved tab collection is invalid");
        }
        List<StoredBankTag> result = new ArrayList<>(source.size());
        Set<String> names = new HashSet<>();
        for (StoredBankTag sourceTab : source)
        {
            if (sourceTab == null)
            {
                throw new IllegalArgumentException("The saved tab collection contains an invalid entry");
            }
            StoredBankTag tab = sourceTab.validatedCopy();
            if (!names.add(tab.getName()))
            {
                throw new IllegalArgumentException("The saved tab collection contains duplicate names");
            }
            result.add(tab);
        }
        return result;
    }
}

package com.banktabstorage;

import java.awt.BorderLayout;
import java.awt.CardLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntFunction;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.DefaultListModel;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ListCellRenderer;
import javax.swing.ListSelectionModel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;

final class BankTabStoragePanel extends PluginPanel
{
    private static final Color BACKGROUND = new Color(40, 40, 40);
    private static final Color SURFACE = new Color(53, 53, 53);
    private static final Color SELECTED = new Color(72, 72, 72);
    private static final Color BUTTON = new Color(68, 68, 68);
    private static final Color GOLD = new Color(214, 180, 92);
    private static final Color GREEN = new Color(122, 184, 111);
    private static final Color MUTED = new Color(174, 174, 174);
    private static final Color DANGER = new Color(225, 121, 111);
    private static final String LIST_CARD = "list";
    private static final String EMPTY_CARD = "empty";
    private final StorageActions actions;
    private final IntFunction<BufferedImage> imageProvider;
    private final DefaultListModel<StoredBankTag> tabModel = new DefaultListModel<>();
    private final JList<StoredBankTag> tabList = new JList<>(tabModel);
    private final Map<Integer, BufferedImage> itemImages = new HashMap<>();
    private final CardLayout contentLayout = new CardLayout();
    private final JPanel content = new JPanel(contentLayout);
    private final JLabel countLabel = new JLabel();
    private final JLabel noticeLabel = new JLabel("Save the tabs you want to keep ready");
    private final JButton loadButton;
    private final JButton toggleButton;
    private final JButton removeButton;

    BankTabStoragePanel(StorageActions actions, IntFunction<BufferedImage> imageProvider)
    {
        super(false);
        this.actions = actions;
        this.imageProvider = imageProvider;
        setLayout(new BorderLayout(0, 10));
        setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        setBackground(BACKGROUND);

        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setOpaque(false);

        JLabel title = new JLabel("Bank Tab Storage");
        title.setForeground(Color.WHITE);
        title.setFont(title.getFont().deriveFont(Font.BOLD, 16f));
        title.setAlignmentX(Component.LEFT_ALIGNMENT);
        header.add(title);

        JLabel subtitle = new JLabel("Your bank tab vault");
        subtitle.setForeground(MUTED);
        subtitle.setFont(subtitle.getFont().deriveFont(11f));
        subtitle.setAlignmentX(Component.LEFT_ALIGNMENT);
        header.add(subtitle);
        header.add(Box.createVerticalStrut(9));

        JPanel status = new JPanel(new BorderLayout());
        status.setAlignmentX(Component.LEFT_ALIGNMENT);
        status.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        status.setBackground(SURFACE);
        status.setBorder(BorderFactory.createCompoundBorder(
            BorderFactory.createMatteBorder(0, 3, 0, 0, GOLD),
            BorderFactory.createEmptyBorder(6, 8, 6, 8)));
        countLabel.setForeground(Color.WHITE);
        countLabel.setFont(countLabel.getFont().deriveFont(Font.BOLD, 11f));
        status.add(countLabel, BorderLayout.CENTER);
        header.add(status);
        header.add(Box.createVerticalStrut(8));

        JButton saveButton = button("Save current tabs", GOLD);
        saveButton.setAlignmentX(Component.LEFT_ALIGNMENT);
        saveButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
        saveButton.addActionListener(event -> actions.saveCurrentTabs());
        header.add(saveButton);
        header.add(Box.createVerticalStrut(5));

        JPanel transferActions = new JPanel(new GridLayout(1, 2, 5, 0));
        transferActions.setOpaque(false);
        transferActions.setAlignmentX(Component.LEFT_ALIGNMENT);
        transferActions.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
        JButton importButton = button("Import", Color.WHITE);
        importButton.addActionListener(event -> importFromClipboard());
        transferActions.add(importButton);
        JButton exportButton = button("Export all", Color.WHITE);
        exportButton.addActionListener(event -> exportToClipboard());
        transferActions.add(exportButton);
        header.add(transferActions);
        add(header, BorderLayout.NORTH);

        configureList();
        JScrollPane scrollPane = new JScrollPane(tabList);
        scrollPane.setBorder(BorderFactory.createEmptyBorder());
        scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.getViewport().setBackground(BACKGROUND);
        content.setOpaque(false);
        content.add(scrollPane, LIST_CARD);
        content.add(emptyState(), EMPTY_CARD);
        add(content, BorderLayout.CENTER);

        JPanel footer = new JPanel(new BorderLayout(0, 7));
        footer.setOpaque(false);
        JPanel selectedActions = new JPanel(new GridLayout(1, 3, 5, 0));
        selectedActions.setOpaque(false);
        loadButton = button("Load", Color.WHITE);
        loadButton.addActionListener(event -> loadSelected());
        selectedActions.add(loadButton);
        toggleButton = button("Show", GREEN);
        toggleButton.addActionListener(event -> toggleSelected());
        selectedActions.add(toggleButton);
        removeButton = button("Remove", DANGER);
        removeButton.addActionListener(event -> removeSelected());
        selectedActions.add(removeButton);
        footer.add(selectedActions, BorderLayout.NORTH);
        noticeLabel.setForeground(MUTED);
        noticeLabel.setFont(noticeLabel.getFont().deriveFont(10f));
        footer.add(noticeLabel, BorderLayout.SOUTH);
        add(footer, BorderLayout.SOUTH);
        updateSelection();
        updateCount();
    }

    void setTabs(List<StoredBankTag> tabs, String notice)
    {
        String selectedName = selectedName();
        tabModel.clear();
        Set<Integer> currentImageIds = new HashSet<>();
        for (StoredBankTag tab : tabs)
        {
            tabModel.addElement(tab.copy());
            currentImageIds.add(tab.getIconItemId());
            itemImage(tab.getIconItemId());
        }
        itemImages.keySet().retainAll(currentImageIds);
        if (selectedName != null)
        {
            selectByName(selectedName);
        }
        if (tabList.getSelectedIndex() < 0 && !tabModel.isEmpty())
        {
            tabList.setSelectedIndex(0);
        }
        if (notice != null && !notice.isEmpty())
        {
            noticeLabel.setText(notice);
        }
        updateCount();
        updateSelection();
        contentLayout.show(content, tabModel.isEmpty() ? EMPTY_CARD : LIST_CARD);
    }

    void showError(String message)
    {
        JOptionPane.showMessageDialog(this, message, "Bank Tab Storage", JOptionPane.ERROR_MESSAGE);
    }

    private void configureList()
    {
        tabList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        tabList.setCellRenderer(new TabRenderer());
        tabList.setBackground(BACKGROUND);
        tabList.setForeground(Color.WHITE);
        tabList.setFixedCellHeight(70);
        tabList.addListSelectionListener(event ->
        {
            if (!event.getValueIsAdjusting())
            {
                updateSelection();
            }
        });
        tabList.addMouseListener(new java.awt.event.MouseAdapter()
        {
            @Override
            public void mouseClicked(java.awt.event.MouseEvent event)
            {
                if (event.getClickCount() == 2)
                {
                    loadSelected();
                }
            }
        });
    }

    private JPanel emptyState()
    {
        JPanel panel = new JPanel();
        panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
        panel.setBackground(BACKGROUND);
        panel.add(Box.createVerticalGlue());
        JLabel title = new JLabel("The vault is empty");
        title.setForeground(Color.WHITE);
        title.setFont(title.getFont().deriveFont(Font.BOLD, 14f));
        title.setAlignmentX(Component.CENTER_ALIGNMENT);
        panel.add(title);
        panel.add(Box.createVerticalStrut(5));
        JLabel detail = new JLabel("Save your visible Bank Tags tabs");
        detail.setForeground(MUTED);
        detail.setFont(detail.getFont().deriveFont(11f));
        detail.setAlignmentX(Component.CENTER_ALIGNMENT);
        panel.add(detail);
        panel.add(Box.createVerticalGlue());
        return panel;
    }

    private JButton button(String text, Color foreground)
    {
        JButton button = new JButton(text);
        button.setFocusPainted(false);
        button.setBackground(BUTTON);
        button.setForeground(foreground);
        button.setMargin(new Insets(2, 4, 2, 4));
        return button;
    }

    private void loadSelected()
    {
        StoredBankTag tab = tabList.getSelectedValue();
        if (tab == null)
        {
            return;
        }
        int choice = JOptionPane.showConfirmDialog(this,
            "Load '" + tab.getName() + "'? This replaces its current tagged items, icon, and layout.",
            "Load saved tab", JOptionPane.OK_CANCEL_OPTION);
        if (choice == JOptionPane.OK_OPTION)
        {
            actions.loadTab(tab.getName());
        }
    }

    private void toggleSelected()
    {
        StoredBankTag tab = tabList.getSelectedValue();
        if (tab != null)
        {
            actions.setTabEnabled(tab.getName(), !tab.isEnabled());
        }
    }

    private void removeSelected()
    {
        StoredBankTag tab = tabList.getSelectedValue();
        if (tab == null)
        {
            return;
        }
        int choice = JOptionPane.showConfirmDialog(this,
            "Remove '" + tab.getName() + "' from storage? The live Bank Tags data will be kept.",
            "Remove saved tab", JOptionPane.OK_CANCEL_OPTION);
        if (choice == JOptionPane.OK_OPTION)
        {
            actions.removeTab(tab.getName());
        }
    }

    private void importFromClipboard()
    {
        try
        {
            Object value = Toolkit.getDefaultToolkit().getSystemClipboard().getData(DataFlavor.stringFlavor);
            if (value == null)
            {
                throw new IllegalArgumentException("The clipboard does not contain text");
            }
            Object[] options = {"Merge", "Replace", "Cancel"};
            int choice = JOptionPane.showOptionDialog(this,
                "How should the clipboard tabs be imported?", "Import saved tabs",
                JOptionPane.DEFAULT_OPTION, JOptionPane.QUESTION_MESSAGE, null, options, options[0]);
            if (choice == 0 || choice == 1)
            {
                actions.importText(value.toString(), choice == 1);
            }
        }
        catch (Exception exception)
        {
            showError(exception.getMessage() == null ? "Unable to read the clipboard" : exception.getMessage());
        }
    }

    private void exportToClipboard()
    {
        if (tabModel.isEmpty())
        {
            showError("There are no saved tabs to export");
            return;
        }
        try
        {
            StringSelection selection = new StringSelection(actions.exportText());
            Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, null);
            noticeLabel.setText("Copied all saved tabs to the clipboard");
        }
        catch (Exception exception)
        {
            showError(exception.getMessage() == null ? "Unable to write to the clipboard" : exception.getMessage());
        }
    }

    private void updateSelection()
    {
        StoredBankTag selected = tabList.getSelectedValue();
        boolean available = selected != null;
        loadButton.setEnabled(available);
        toggleButton.setEnabled(available);
        removeButton.setEnabled(available);
        if (selected == null)
        {
            toggleButton.setText("Show");
            toggleButton.setForeground(GREEN);
        }
        else
        {
            toggleButton.setText(selected.isEnabled() ? "Hide" : "Show");
            toggleButton.setForeground(selected.isEnabled() ? GOLD : GREEN);
        }
    }

    private void updateCount()
    {
        int visible = 0;
        for (int index = 0; index < tabModel.size(); index++)
        {
            if (tabModel.get(index).isEnabled())
            {
                visible++;
            }
        }
        countLabel.setText(tabModel.size() + " stored  |  " + visible + " visible in bank");
    }

    private String selectedName()
    {
        StoredBankTag selected = tabList.getSelectedValue();
        return selected == null ? null : selected.getName();
    }

    private void selectByName(String name)
    {
        for (int index = 0; index < tabModel.size(); index++)
        {
            if (tabModel.get(index).getName().equals(name))
            {
                tabList.setSelectedIndex(index);
                return;
            }
        }
    }

    private BufferedImage itemImage(int itemId)
    {
        BufferedImage image = itemImages.get(itemId);
        if (image != null)
        {
            return image;
        }
        image = imageProvider.apply(itemId);
        if (image == null)
        {
            return null;
        }
        itemImages.put(itemId, image);
        if (image instanceof AsyncBufferedImage)
        {
            ((AsyncBufferedImage) image).onLoaded(() -> SwingUtilities.invokeLater(tabList::repaint));
        }
        return image;
    }

    private final class TabRenderer extends JPanel implements ListCellRenderer<StoredBankTag>
    {
        private StoredBankTag tab;
        private boolean selected;

        private TabRenderer()
        {
            setOpaque(true);
            setPreferredSize(new Dimension(200, 70));
        }

        @Override
        public Component getListCellRendererComponent(JList<? extends StoredBankTag> list, StoredBankTag value,
            int index, boolean selected, boolean focused)
        {
            this.tab = value;
            this.selected = selected;
            return this;
        }

        @Override
        protected void paintComponent(Graphics graphics)
        {
            Graphics2D painter = (Graphics2D) graphics.create();
            painter.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
                RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
            painter.setColor(BACKGROUND);
            painter.fillRect(0, 0, getWidth(), getHeight());
            if (tab == null)
            {
                painter.dispose();
                return;
            }
            painter.setColor(selected ? SELECTED : SURFACE);
            painter.fillRect(0, 0, getWidth(), getHeight() - 6);
            int left = 10;
            if (tab.isEnabled())
            {
                painter.setColor(GOLD);
                painter.fillRect(0, 0, 3, getHeight() - 6);
                left = 11;
            }
            BufferedImage image = itemImage(tab.getIconItemId());
            if (image != null)
            {
                painter.drawImage(image, left, 16, null);
            }
            int textLeft = 56;
            String stateText = tab.isEnabled() ? "SHOWING" : "HIDDEN";
            painter.setFont(getFont().deriveFont(Font.BOLD, 9f));
            FontMetrics stateMetrics = painter.getFontMetrics();
            int stateWidth = stateMetrics.stringWidth(stateText);
            painter.setColor(tab.isEnabled() ? GREEN : MUTED);
            painter.drawString(stateText, getWidth() - stateWidth - 8, 24);

            painter.setFont(getFont().deriveFont(Font.BOLD, 12f));
            painter.setColor(Color.WHITE);
            painter.drawString(clipText(tab.getName(), painter.getFontMetrics(),
                getWidth() - textLeft - stateWidth - 18), textLeft, 24);

            int count = tab.getItemCount();
            String details = count + (count == 1 ? " item" : " items")
                + "  |  " + (tab.hasLayout() ? "Layout saved" : "No layout");
            painter.setFont(getFont().deriveFont(10f));
            painter.setColor(MUTED);
            painter.drawString(clipText(details, painter.getFontMetrics(), getWidth() - textLeft - 8),
                textLeft, 44);
            painter.dispose();
        }

        private String clipText(String value, FontMetrics metrics, int width)
        {
            if (width <= 0 || metrics.stringWidth(value) <= width)
            {
                return width <= 0 ? "" : value;
            }
            String suffix = "...";
            int limit = Math.max(0, width - metrics.stringWidth(suffix));
            int end = value.length();
            while (end > 0 && metrics.stringWidth(value.substring(0, end)) > limit)
            {
                end--;
            }
            return value.substring(0, end) + suffix;
        }
    }
}

package com.banktabstorage;

import com.google.gson.Gson;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDependency;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@PluginDescriptor(
    name = "Bank Tab Storage",
    description = "Save, restore, show, hide, import, and export complete Bank Tags tabs. Requires the Bank Tags plugin!",
    tags = {"bank", "tags", "storage", "layout", "loadout", "preset"}
)
@PluginDependency(BankTagsPlugin.class)
public final class BankTabStoragePlugin extends Plugin implements StorageActions
{
    private static final String CONFIG_GROUP = "banktabstorage";
    private static final String LEGACY_CONFIG_GROUP = "banktagsstorage";
    private static final String CONFIG_KEY = "savedTabs";
    private volatile List<StoredBankTag> storedTabs = List.of();
    private volatile boolean changingBankTabs;

    @Inject
    private Gson gson;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private ConfigManager configManager;

    @Inject
    private ItemManager itemManager;

    @Inject
    private TagManager tagManager;

    @Inject
    private LayoutManager layoutManager;

    @Inject
    private BankTagsService bankTagsService;

    private BankTagsAccess bankTags;
    private BankTabStorageCodec codec;
    private BankTabStoragePanel panel;
    private NavigationButton navigationButton;

    @Override
    protected void startUp()
    {
        codec = new BankTabStorageCodec(gson);
        bankTags = new BankTagsAccess(configManager, tagManager, layoutManager,
            new BankTagTabsReloader(configManager, client), bankTagsService);
        loadStorage();
        storedTabs = immutable(StoredTabCollection.syncEnabled(storedTabs, bankTags.visibleNames()));
        SwingUtilities.invokeLater(() ->
        {
            panel = new BankTabStoragePanel(this, itemManager::getImage);
            panel.setTabs(storedTabs, "Save the tabs you want to keep ready");
            navigationButton = NavigationButton.builder()
                .tooltip("Bank Tab Storage")
                .icon(createNavigationIcon())
                .priority(5)
                .panel(panel)
                .build();
            clientToolbar.addNavigation(navigationButton);
        });
    }

    @Override
    protected void shutDown()
    {
        SwingUtilities.invokeLater(() ->
        {
            if (navigationButton != null)
            {
                clientToolbar.removeNavigation(navigationButton);
            }
            navigationButton = null;
            panel = null;
        });
        bankTags = null;
        codec = null;
        storedTabs = List.of();
        changingBankTabs = false;
    }

    @Subscribe
    public void onProfileChanged(ProfileChanged event)
    {
        clientThread.invokeLater(() ->
        {
            loadStorage();
            storedTabs = immutable(StoredTabCollection.syncEnabled(storedTabs, bankTags.visibleNames()));
            publish("Loaded storage for the active profile");
        });
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!changingBankTabs
            && BankTagsPlugin.CONFIG_GROUP.equals(event.getGroup())
            && BankTagsPlugin.TAG_TABS_CONFIG.equals(event.getKey()))
        {
            clientThread.invokeLater(() ->
            {
                storedTabs = immutable(StoredTabCollection.syncEnabled(storedTabs, bankTags.visibleNames()));
                persist();
                publish("Bank tab visibility updated");
            });
        }
    }

    @Override
    public void saveCurrentTabs()
    {
        runOnClient(() ->
        {
            List<StoredBankTag> current = bankTags.captureVisibleTabs();
            storedTabs = immutable(StoredTabCollection.merge(storedTabs, current, false));
            storedTabs = immutable(StoredTabCollection.syncEnabled(storedTabs, bankTags.visibleNames()));
            persist();
            publish(current.isEmpty() ? "No visible Bank Tags tabs were found"
                : "Saved " + current.size() + (current.size() == 1 ? " visible tab" : " visible tabs"));
        });
    }

    @Override
    public void loadTab(String name)
    {
        runOnClient(() ->
        {
            StoredBankTag tab = requireTab(name);
            changingBankTabs = true;
            try
            {
                bankTags.applySnapshot(tab);
                bankTags.setVisible(tab.getName(), true);
                bankTags.refreshBank(tab.getName(), false);
            }
            finally
            {
                changingBankTabs = false;
            }
            storedTabs = immutable(StoredTabCollection.setEnabled(storedTabs, tab.getName(), true));
            persist();
            publish("Loaded '" + tab.getName() + "' into Bank Tags");
        });
    }

    @Override
    public void setTabEnabled(String name, boolean enabled)
    {
        runOnClient(() ->
        {
            StoredBankTag tab = requireTab(name);
            changingBankTabs = true;
            try
            {
                bankTags.setVisible(tab.getName(), enabled);
                bankTags.refreshBank(tab.getName(), !enabled);
            }
            finally
            {
                changingBankTabs = false;
            }
            storedTabs = immutable(StoredTabCollection.setEnabled(storedTabs, tab.getName(), enabled));
            persist();
            publish((enabled ? "Showing '" : "Hid '") + tab.getName() + "'");
        });
    }

    @Override
    public void removeTab(String name)
    {
        runOnClient(() ->
        {
            StoredBankTag tab = requireTab(name);
            changingBankTabs = true;
            try
            {
                bankTags.setVisible(tab.getName(), false);
                bankTags.refreshBank(tab.getName(), true);
            }
            finally
            {
                changingBankTabs = false;
            }
            storedTabs = immutable(StoredTabCollection.remove(storedTabs, tab.getName()));
            persist();
            publish("Removed '" + tab.getName() + "' from storage");
        });
    }

    @Override
    public void importText(String text, boolean replace)
    {
        List<StoredBankTag> imported;
        try
        {
            imported = codec.decode(text);
        }
        catch (IllegalArgumentException exception)
        {
            showError(exception.getMessage());
            return;
        }
        runOnClient(() ->
        {
            storedTabs = immutable(StoredTabCollection.merge(storedTabs, imported, replace));
            storedTabs = immutable(StoredTabCollection.syncEnabled(storedTabs, bankTags.visibleNames()));
            persist();
            publish("Imported " + imported.size() + (imported.size() == 1 ? " saved tab" : " saved tabs"));
        });
    }

    @Override
    public String exportText()
    {
        return codec.encode(storedTabs);
    }

    private void runOnClient(Runnable action)
    {
        clientThread.invokeLater(() ->
        {
            try
            {
                action.run();
            }
            catch (RuntimeException exception)
            {
                showError(exception.getMessage() == null ? "The Bank Tags operation failed" : exception.getMessage());
            }
        });
    }

    private StoredBankTag requireTab(String name)
    {
        StoredBankTag tab = StoredTabCollection.find(storedTabs, name);
        if (tab == null)
        {
            throw new IllegalArgumentException("The selected saved tab no longer exists");
        }
        return tab;
    }

    private void loadStorage()
    {
        String json = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY);
        boolean legacy = false;
        if (json == null || json.trim().isEmpty())
        {
            json = configManager.getConfiguration(LEGACY_CONFIG_GROUP, CONFIG_KEY);
            legacy = json != null && !json.trim().isEmpty();
        }
        if (json == null || json.trim().isEmpty())
        {
            storedTabs = List.of();
            return;
        }
        try
        {
            storedTabs = immutable(codec.decode(json));
            if (legacy)
            {
                persist();
                configManager.unsetConfiguration(LEGACY_CONFIG_GROUP, CONFIG_KEY);
            }
        }
        catch (IllegalArgumentException exception)
        {
            storedTabs = List.of();
        }
    }

    private void persist()
    {
        configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY, codec.encode(storedTabs));
    }

    private void publish(String notice)
    {
        List<StoredBankTag> snapshot = immutable(storedTabs);
        SwingUtilities.invokeLater(() ->
        {
            if (panel != null)
            {
                panel.setTabs(snapshot, notice);
            }
        });
    }

    private void showError(String message)
    {
        SwingUtilities.invokeLater(() ->
        {
            if (panel != null)
            {
                panel.showError(message);
            }
        });
    }

    private static List<StoredBankTag> immutable(List<StoredBankTag> source)
    {
        List<StoredBankTag> result = new ArrayList<>(source.size());
        for (StoredBankTag tab : source)
        {
            result.add(tab.copy());
        }
        return List.copyOf(result);
    }

    private static BufferedImage createNavigationIcon()
    {
        return ImageUtil.loadImageResource(BankTabStoragePlugin.class, "sidebar-icon.png");
    }
}

